/* ===================== BÀI 1 · Một ca sản xuất khi chưa có MES ===================== */
/* Bài 1 · Một ca sản xuất khi chưa có MES (MS01.01) — sinh bởi tools/author/mes/m01.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l1"),{id:"l1",scenarios:[{"label": "Ví dụ: Sản lượng đi bằng giấy", "note": "Đếm thời gian từ lúc có sự cố tới lúc người quyết định biết.", "steps": [{"t": "06:00 · Ca 1 bắt đầu", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Giờ<\/th><th scope=\"col\">Việc<\/th><th scope=\"col\">Ai biết số sản lượng?<\/th><\/tr><\/thead><tbody><tr><td>06:00<\/td><td>Máy M1 bắt đầu rót hộp<\/td><td class=\"hi\">Chỉ bộ đếm của máy<\/td><\/tr><\/tbody><\/table>", "say": "<p>Bộ đếm trên màn hình máy tăng theo từng hộp, nhưng chỉ người đứng cạnh máy nhìn thấy.<\/p>"}, {"t": "Mỗi giờ · Tổ trưởng ghi sổ", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Giờ<\/th><th scope=\"col\">Việc<\/th><th scope=\"col\">Ai biết?<\/th><\/tr><\/thead><tbody><tr><td>06:00<\/td><td>M1 bắt đầu<\/td><td>Bộ đếm<\/td><\/tr><tr><td>07:00 … 14:00<\/td><td>Tổ trưởng chép số đếm vào sổ mỗi giờ<\/td><td class=\"hi\">Tổ trưởng<\/td><\/tr><\/tbody><\/table>"}, {"t": "14:30 · Cộng sổ, nhập Excel", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Giờ<\/th><th scope=\"col\">Việc<\/th><th scope=\"col\">Ai biết?<\/th><\/tr><\/thead><tbody><tr><td>06:00<\/td><td>M1 bắt đầu<\/td><td>Bộ đếm<\/td><\/tr><tr><td>07:00 … 14:00<\/td><td>Ghi sổ mỗi giờ<\/td><td>Tổ trưởng<\/td><\/tr><tr><td>14:30<\/td><td>Cộng sổ, nhập Excel, gửi email<\/td><td class=\"hi\">Văn phòng xưởng<\/td><\/tr><\/tbody><\/table>"}, {"t": "08:00 hôm sau · Họp giao ban", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Giờ<\/th><th scope=\"col\">Việc<\/th><th scope=\"col\">Ai biết?<\/th><\/tr><\/thead><tbody><tr><td>06:00<\/td><td>M1 bắt đầu<\/td><td>Bộ đếm<\/td><\/tr><tr><td>07:00 … 14:00<\/td><td>Ghi sổ mỗi giờ<\/td><td>Tổ trưởng<\/td><\/tr><tr><td>14:30<\/td><td>Nhập Excel<\/td><td>Văn phòng<\/td><\/tr><tr><td>08:00 hôm sau<\/td><td>Trưởng xưởng đọc báo cáo<\/td><td class=\"hi\">Trưởng xưởng<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Một sự cố lúc 07:00 sáng nay tới tay trưởng xưởng sau bao lâu?", "o": ["1 giờ", "7 giờ 30 phút", "25 giờ"], "a": 2}}, {"t": "Kết luận: thông tin trễ 25 giờ", "html": "<p class=\"mt-calc\">07:00 hôm nay → 08:00 hôm sau = <b>25 giờ<\/b><\/p>", "say": "<p>Số liệu không sai, nhưng tới quá muộn để sửa chính ca đó. Người quyết định luôn nhìn vào quá khứ.<\/p>"}]}, {"label": "Ví dụ: Cùng con số khi có MES", "note": "Quan sát số hộp đi thẳng từ PLC lên màn hình, không qua chép tay.", "steps": [{"t": "Hộp thứ 1 rời máy M1", "html": "<div class=\"mt-flow\"><div class=\"mt-box on\"><b>Cảm biến<\/b><small>thấy hộp<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>PLC FX5U<\/b><small>D102 = 1<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Collector<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>CSDL MES<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Màn hình<\/b><\/div><\/div>"}, {"t": "PLC tăng bộ đếm", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>Cảm biến<\/b><small>thấy hộp<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>PLC FX5U<\/b><small>D102 = 1<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Collector<\/b><small>đọc mỗi 1 s<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>CSDL MES<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Màn hình<\/b><\/div><\/div>"}, {"t": "Collector đọc PLC qua mạng", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>Cảm biến<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>PLC FX5U<\/b><small>D102 = 1<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Collector<\/b><small>đọc mỗi 1 s<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>CSDL MES<\/b><small>ghi số tăng thêm<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Màn hình<\/b><\/div><\/div>"}, {"t": "MES ghi và màn hình cập nhật", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>Cảm biến<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>PLC FX5U<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Collector<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>CSDL MES<\/b><small>đã ghi<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Màn hình<\/b><small>1 hộp<\/small><\/div><\/div><p class=\"mt-calc\">Độ trễ ≈ chu kỳ đọc 1 s + thời gian ghi và đẩy lên màn hình (giả định: dưới 2 s)<\/p>", "say": "<p>Ai cũng xem được cùng một con số gần như ngay lập tức. Con số do máy đếm, không qua chép tay.<\/p>", "ask": {"q": "Collector đọc PLC mỗi 1 giây. Độ trễ nhỏ nhất có thể là bao nhiêu?", "o": ["Khoảng 1 giây", "Khoảng 1 giờ", "Đúng 0 giây"], "a": 0}}]}, {"label": "Ví dụ: Phát hiện nạp sai hạt muộn", "note": "Số hộp sai = thời gian tới khi phát hiện chia cho chu kỳ máy.", "steps": [{"t": "08:00 · Máy rót nhầm loại hạt", "html": "<p class=\"mt-calc\">Lệnh yêu cầu hạt điều rang muối, phễu lại nạp hạt điều không muối.<\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thông số<\/th><th scope=\"col\">Giá trị<\/th><\/tr><\/thead><tbody><tr><td>Chu kỳ M1<\/td><td>2,0 s/hộp (giả định)<\/td><\/tr><tr><td>Máy chạy liên tục<\/td><td>có<\/td><\/tr><\/tbody><\/table>"}, {"t": "Phát hiện lúc 10:00 (kiểm tra bằng tay)", "html": "<p class=\"mt-calc\">Thời gian chạy sai: 120 phút = 7 200 s → 7 200 / 2,0 = <b>3 600 hộp<\/b> phải xử lý lại<\/p>", "ask": {"q": "Máy chạy sai 120 phút với chu kỳ 2,0 s. Bao nhiêu hộp sai?", "o": ["60", "3 600", "7 200"], "a": 1}}, {"t": "Nếu MES chặn sau 5 phút", "html": "<p class=\"mt-calc\">5 phút = 300 s → 300 / 2,0 = <b>150 hộp<\/b><\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Phát hiện sau<\/th><th scope=\"col\">Số hộp sai<\/th><\/tr><\/thead><tbody><tr><td>120 phút<\/td><td>3 600<\/td><\/tr><tr><td>5 phút<\/td><td class=\"ok\">150<\/td><\/tr><\/tbody><\/table>", "say": "<p>Số hộp sai tỷ lệ thuận với thời gian phát hiện. MES rút ngắn thời gian này bằng cách kiểm tra lô nguyên liệu khi nạp (Chương 16).<\/p>"}]}, {"label": "Ví dụ: Sổ tay bỏ sót dừng ngắn", "note": "So sánh số lần dừng trong sổ với số lần PLC ghi được.", "steps": [{"t": "Sổ tay ghi 3 lần dừng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Lần<\/th><th scope=\"col\">Phút<\/th><th scope=\"col\">Ghi chú<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>10<\/td><td>Kẹt màng<\/td><\/tr><tr><td>2<\/td><td>8<\/td><td>Đổi cuộn nhãn<\/td><\/tr><tr><td>3<\/td><td>7<\/td><td>Chờ hạt<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">Tổng theo sổ: <b>25 phút<\/b><\/p>"}, {"t": "PLC ghi 11 lần dừng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Loại<\/th><th scope=\"col\">Số lần<\/th><th scope=\"col\">Tổng phút<\/th><\/tr><\/thead><tbody><tr><td>Dừng dài (≥ 5 phút)<\/td><td>3<\/td><td>25<\/td><\/tr><tr><td class=\"hi\">Dừng ngắn (< 5 phút)<\/td><td class=\"hi\">8<\/td><td class=\"hi\">16<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Tổng thời gian dừng thật là bao nhiêu phút?", "o": ["25", "16", "41"], "a": 2}}, {"t": "Sổ tay bỏ sót 39 % thời gian dừng", "html": "<p class=\"mt-calc\">16 / 41 ≈ <b>39 %<\/b> thời gian dừng không có trong sổ<\/p>", "say": "<p>Dừng ngắn không ai ghi vì mỗi lần chỉ một, hai phút, nhưng cộng lại rất lớn. Dữ liệu lấy thẳng từ PLC thấy được tổn thất này (Chương 3, 13).<\/p>"}]}, {"label": "Bẫy: Cộng sổ đảo chữ số", "note": "Báo cáo thừa 90 hộp chỉ vì đảo hai chữ số khi cộng tay.", "steps": [{"t": "Sổ ghi 4 giờ đầu ca", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Giờ<\/th><th scope=\"col\">Số hộp<\/th><\/tr><\/thead><tbody><tr><td>7:00<\/td><td>1 820<\/td><\/tr><tr><td>8:00<\/td><td>1 795<\/td><\/tr><tr><td>9:00<\/td><td>1 810<\/td><\/tr><tr><td>10:00<\/td><td>1 805<\/td><\/tr><\/tbody><\/table>"}, {"t": "Tổ trưởng cộng được 7 320", "html": "<p class=\"mt-calc\">Tổng ghi vào Excel: <b>7 320<\/b><\/p>", "ask": {"q": "Tổng đúng của bốn số là bao nhiêu?", "o": ["7 320", "7 230", "7 203"], "a": 1}}, {"t": "Tổng đúng là 7 230", "html": "<p class=\"mt-calc\">1 820 + 1 795 + 1 810 + 1 805 = <b>7 230<\/b> · báo cáo thừa 90 hộp<\/p>", "say": "<p>Lỗi đảo chữ số (7 230 thành 7 320) rất khó thấy bằng mắt. Khi máy tự đếm và phần mềm tự cộng, khâu chép tay và cộng tay biến mất.<\/p>"}]}, {"label": "Lỗi: Đếm hộp lỗi hai lần", "note": "Hai nơi cùng ghi một dữ liệu làm tỷ lệ đạt bị kéo xuống.", "steps": [{"t": "Hai nơi cùng ghi hộp lỗi", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Nơi ghi<\/th><th scope=\"col\">Hộp lỗi<\/th><\/tr><\/thead><tbody><tr><td>Máy cân kiểm tra M3<\/td><td>300<\/td><\/tr><tr><td>Phiếu của bộ phận chất lượng<\/td><td>300 (cùng 300 hộp đó)<\/td><\/tr><\/tbody><\/table>"}, {"t": "Excel cộng cả hai", "html": "<p class=\"mt-calc\">Hộp lỗi = 300 + 300 = 600 → tỷ lệ đạt = 10 200 / 10 800 = <b>0,9444<\/b><\/p>", "ask": {"q": "Tỷ lệ đạt đúng là bao nhiêu?", "o": ["0,9444", "0,9714", "1,0000"], "a": 1}}, {"t": "Sửa: mỗi hộp lỗi chỉ ghi một lần", "html": "<p class=\"mt-calc\">Tỷ lệ đạt đúng = 10 200 / 10 500 = <b>0,9714<\/b><\/p>", "say": "<p>Mỗi dữ liệu phải có <b>một nơi sở hữu<\/b>. Câu hỏi “ai ghi số này” được trả lời ở Bài 4.<\/p>"}]}, {"label": "Bẫy: Có Excel là có MES", "note": "Excel tổng hợp quá khứ, không làm việc trong lúc sản xuất.", "steps": [{"t": "Xưởng đã có file Excel báo cáo", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Câu hỏi<\/th><th scope=\"col\">Excel cuối ca<\/th><\/tr><\/thead><tbody><tr><td>Tổng sản lượng hôm qua?<\/td><td class=\"ok\">Trả lời được<\/td><\/tr><\/tbody><\/table>"}, {"t": "Hỏi thêm ba câu", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Câu hỏi<\/th><th scope=\"col\">Excel cuối ca<\/th><\/tr><\/thead><tbody><tr><td>Tổng sản lượng hôm qua?<\/td><td class=\"ok\">Trả lời được<\/td><\/tr><tr><td>M2 đang dừng vì sao, ngay lúc này?<\/td><td class=\"bad\">Không<\/td><\/tr><tr><td>Hộp này dùng lô hạt nào?<\/td><td class=\"bad\">Không<\/td><\/tr><tr><td>Có chặn được việc nạp sai lô?<\/td><td class=\"bad\">Không<\/td><\/tr><\/tbody><\/table>", "say": "<p>Excel tổng hợp lại quá khứ. MES làm việc <b>trong lúc<\/b> sản xuất: thu thập, kiểm tra, chặn, truy xuất.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l1"),"l1",[{"kind": "num", "t": "Tính số liệu của ca", "d": "<p>Máy M1 có chu kỳ 2,0 s/hộp và chạy liên tục. Trả lời bằng một số. Câu cuối làm tròn tới 4 chữ số thập phân.<\/p>", "items": [{"q": "Nạp sai loại hạt, phát hiện sau 90 phút. Bao nhiêu hộp bị ảnh hưởng?", "a": 2700, "unit": "hộp"}, {"q": "Cùng lỗi đó, MES chặn sau 3 phút. Bao nhiêu hộp bị ảnh hưởng?", "a": 90, "unit": "hộp"}, {"q": "Sổ ghi bốn giờ: 1 820, 1 795, 1 810, 1 805. Tổng đúng là bao nhiêu?", "a": 7230, "unit": "hộp"}, {"q": "Ca có 10 200 hộp đạt và 300 hộp lỗi, nhưng hộp lỗi bị ghi hai lần. Tỷ lệ đạt bị báo sai là bao nhiêu?", "a": 0.9444, "tol": 5e-05}], "hints": ["Đổi phút sang giây trước, rồi chia cho chu kỳ 2,0 s.", "90 phút = 5 400 s; 3 phút = 180 s.", "Ghi hai lần nghĩa là số hộp lỗi bị tính thành 600: tỷ lệ đạt = 10 200 / (10 200 + 600)."], "why": "90 phút = 5 400 s → 2 700 hộp; 3 phút = 180 s → 90 hộp. Tổng bốn giờ là 7 230. Đếm trùng hộp lỗi cho 10 200 / 10 800 ≈ 0,9444 thay vì 0,9714."}, {"kind": "pick", "t": "Sổ tay đủ hay cần MES?", "d": "<p>Với mỗi câu hỏi của xưởng, chọn cách trả lời phù hợp.<\/p>", "cats": ["Sổ tay, báo cáo cuối ca là đủ", "Cần MES (dữ liệu máy theo thời gian thực)"], "items": [{"q": "Tổng sản lượng của tháng trước", "a": 0}, {"q": "Máy M2 đang dừng vì nguyên nhân gì, ngay lúc này", "a": 1}, {"q": "Hộp bị khiếu nại dùng lô hạt điều nào", "a": 1}, {"q": "Ca 1 có bao nhiêu lần dừng dưới 2 phút", "a": 1}, {"q": "Danh sách công nhân trực ca 1 tuần trước", "a": 0}, {"q": "Chặn công nhân nạp nhầm lô nguyên liệu", "a": 1}], "hints": ["Câu hỏi về quá khứ, tổng gộp, ít thay đổi thường không cần dữ liệu máy.", "Câu hỏi về “ngay lúc này”, về từng lần dừng ngắn, hay về một sản phẩm cụ thể cần dữ liệu chi tiết theo thời gian thực.", "Chặn một thao tác sai phải xảy ra trong lúc làm, không thể đợi cuối ca."], "why": "Tổng tháng trước và danh sách trực ca là dữ liệu tổng hợp của quá khứ. Trạng thái hiện tại, dừng ngắn, truy xuất một hộp và chặn thao tác sai đều cần dữ liệu chi tiết lúc đang sản xuất, đó là việc của MES."}, {"kind": "order", "t": "Đường đi của một hộp khi có MES", "d": "<p>Sắp xếp các bước theo đúng thứ tự, từ lúc hộp rời máy tới lúc có quyết định.<\/p>", "items": ["Cảm biến phát hiện hộp rời máy M1", "PLC FX5U tăng bộ đếm D102", "Bộ thu thập dữ liệu đọc D102 qua mạng", "MES ghi số tăng thêm vào cơ sở dữ liệu", "Màn hình xưởng hiện sản lượng mới", "Trưởng ca quyết định có điều chỉnh hay không"], "hints": ["Bắt đầu ở thiết bị gần sản phẩm nhất.", "PLC đếm trước, rồi phần mềm mới đọc được số đếm.", "Phải ghi vào cơ sở dữ liệu thì màn hình mới có số để hiện."], "why": "Dữ liệu đi từ cảm biến (cấp 0) lên PLC (cấp 1), qua bộ thu thập dữ liệu tới MES (cấp 3), rồi tới người quyết định. Không có bước chép tay nào."}]);

makeQuiz("quiz1","score1",[{"q": "Theo bài học, MES làm việc chính nào?", "o": ["Lập kế hoạch tài chính và tính lương cho nhà máy", "Thu thập, theo dõi và điều phối việc thực hiện sản xuất theo thời gian thực", "Điều khiển động cơ và van trong từng mili giây", "Thiết kế bản vẽ sản phẩm mới"], "a": 1, "e": "MES quản lý việc thực hiện sản xuất. Kế hoạch tài chính thuộc ERP, điều khiển mili giây thuộc PLC, bản vẽ thuộc phần mềm thiết kế."}, {"q": "Sự cố lúc 07:00 được biết ở buổi họp 08:00 hôm sau. Thông tin trễ bao lâu?", "o": ["1 giờ", "8 giờ", "25 giờ", "24 giờ"], "a": 2, "e": "Từ 07:00 hôm nay tới 07:00 hôm sau là 24 giờ, thêm 1 giờ tới 08:00 là 25 giờ. Đáp án 24 giờ quên giờ chênh lệch cuối."}, {"q": "Máy chu kỳ 2,0 s chạy sai 30 phút trước khi phát hiện. Bao nhiêu hộp bị ảnh hưởng?", "o": ["900", "60", "15", "1 800"], "a": 0, "e": "30 phút = 1 800 s; 1 800 / 2,0 = 900 hộp. Đáp án 1 800 là quên chia cho chu kỳ."}, {"q": "Vì sao sổ tay thường bỏ sót dừng ngắn?", "o": ["Vì PLC không đếm được dừng ngắn", "Vì dừng ngắn không ảnh hưởng tới sản lượng", "Vì mỗi lần chỉ một, hai phút nên không ai ghi, dù cộng lại rất lớn", "Vì dừng ngắn chỉ xảy ra vào giờ nghỉ"], "a": 2, "e": "Từng lần dừng ngắn có vẻ không đáng ghi, nhưng trong ví dụ 8 lần cộng lại 16 phút, chiếm 39 % tổng thời gian dừng."}, {"q": "Câu nào phân biệt đúng MES với file Excel báo cáo cuối ca?", "o": ["Excel chỉ chạy trên Windows, MES chạy trên mọi máy", "Excel tổng hợp quá khứ; MES làm việc trong lúc sản xuất: thu thập, kiểm tra, chặn, truy xuất", "Excel có nhiều công thức hơn MES", "MES chỉ là Excel có giao diện đẹp hơn"], "a": 1, "e": "Khác biệt không nằm ở công cụ mà ở thời điểm và nguồn dữ liệu: MES lấy dữ liệu từ máy ngay khi xảy ra và có thể chặn thao tác sai."}]);

